  var zp = null, zpLayers = [], zpText, band = null;
  /* Wörter in Masken packen (Überschriften steigen hoch) */
  document.querySelectorAll('.rise').forEach(function (el) {
    var delay = 0, step = 0.055;
    function wrapText(node, soft) {
      var frag = document.createDocumentFragment();
      var parts = node.nodeValue.split(/(\s+)/);
      parts.forEach(function (t) {
        if (!t) return;
        if (/^\s+$/.test(t)) { frag.appendChild(document.createTextNode(' ')); return; }
        var w = document.createElement('span'); w.className = 'w';
        var wi = document.createElement('span'); wi.className = 'wi' + (soft ? ' soft' : ''); wi.textContent = t;
        wi.style.transitionDelay = delay.toFixed(3) + 's'; delay += step;
        w.appendChild(wi); frag.appendChild(w);
      });
      return frag;
    }
    function walk(parent, soft) {
      Array.prototype.slice.call(parent.childNodes).forEach(function (n) {
        if (n.nodeType === 3) { parent.replaceChild(wrapText(n, soft), n); }
        else if (n.nodeType === 1) {
          var isSoft = soft || n.classList.contains('soft');
          if (n.tagName === 'EM' || n.tagName === 'SPAN') { n.classList.remove('soft'); walk(n, isSoft); }
        }
      });
    }
    walk(el, false);
  });

  /* Film-Sätze: Buchstaben rollen, {…} im Verlauf */
  document.querySelectorAll('[data-roll]').forEach(function (el) {
    var txt = el.getAttribute('data-roll'), t = 0.15 + parseFloat(el.dataset.delay || 0), step = 0.02;
    var m = /^(.*?)\s*\{([^}]+)\}(.*)$/.exec(txt);
    var chunks = m ? [[m[1], false], [m[2], true], [m[3], false]] : [[txt, false]];
    chunks.forEach(function (c, ci) {
      if (!c[0]) return;
      if (ci === 1) t += parseFloat(el.dataset.gap || 0.28);
      var total = Array.from(c[0].replace(/\s+/g, '')).length, li = 0;
      c[0].trim().split(/\s+/).forEach(function (word, wi, arr) {
        if (el.childNodes.length > 1) el.appendChild(document.createTextNode(' '));
        var rw = document.createElement('span'); rw.className = 'rw'; rw.setAttribute('aria-hidden', 'true');
        Array.from(word).forEach(function (ch) {
          var rm = document.createElement('span'); rm.className = 'rm';
          var rc = document.createElement('span'); rc.className = 'rc' + (c[1] ? ' rb' : ''); rc.textContent = ch;
          if (c[1]) { rc.style.setProperty('--a', (li / total).toFixed(3)); rc.style.setProperty('--b', ((li + 1) / total).toFixed(3)); li++; }
          t += step; rc.style.transitionDelay = t.toFixed(3) + 's';
          rm.appendChild(rc); rw.appendChild(rm);
        });
        el.appendChild(rw); t += step;
      });
    });
  });


  /* Hero: markiertes Wort flackert Buchstabe für Buchstabe im Verlauf an (wie „offline" auf der Website) */
  document.querySelectorAll('[data-flicker]').forEach(function (el) {
    var word = el.textContent, letters = Array.from(word), n = letters.length; el.textContent = '';
    letters.forEach(function (ch, i) {
      var s = document.createElement('span'); s.className = 'fl'; s.textContent = ch;
      s.style.setProperty('--a', (i / n).toFixed(3)); s.style.setProperty('--b', ((i + 1) / n).toFixed(3));
      s.style.animationDelay = (parseFloat(el.dataset.fd || 1.05) + i * 0.09).toFixed(2) + 's'; el.appendChild(s);
    });
  });
  /* Laufband läuft nur im Bild */
  document.querySelectorAll('.mq').forEach(function (mq) { var track = mq.querySelector('.mq-track'); new IntersectionObserver(function (e) { track.dataset.paused = e[0].isIntersecting ? 'false' : 'true'; }, { threshold: 0 }).observe(mq); });

  /* Bühnen 05/06: Fortschritt aus dem Scrollweg, Schritt-Klasse schaltet, die Übergänge macht CSS */
  var stages = Array.prototype.map.call(document.querySelectorAll('[data-stage]'), function (el) {
    return { el: el, n: parseInt(el.dataset.steps, 10), steps: el.querySelectorAll('.step'), dots: el.querySelectorAll('.step-dots i'), lives: el.querySelectorAll('.life'), hots: el.querySelectorAll('.hot'), cur: -1 };
  });
  function stageTick() {
    stages.forEach(function (st) {
      var r = st.el.getBoundingClientRect(), total = r.height - innerHeight; if (total <= 0) return;
      if (r.top < innerHeight * 0.8 && r.bottom > 0) st.el.classList.add('on');
      var p = Math.min(1, Math.max(0, -r.top / total)), i = Math.min(st.n - 1, Math.floor(p * st.n * 0.985));
      if (r.top > innerHeight * 0.6) i = 0;
      if (i === st.cur) return;
      var prev = st.cur; st.cur = i; st.el.dataset.step = i;
      st.steps.forEach(function (e, k) { e.classList.toggle('is', k === i); e.classList.toggle('was', k < i); });
      st.dots.forEach(function (d, k) { d.classList.toggle('on', k <= i); });
      st.lives.forEach(function (l, k) { l.classList.toggle('is', k === i); l.classList.toggle('was', k < i); });
      st.hots.forEach(function (h) { h.classList.toggle('live', parseInt(h.dataset.on, 10) === i); });
    });
  }
  if (stages.length) { addEventListener('scroll', function () { requestAnimationFrame(stageTick); }, { passive: true }); addEventListener('resize', stageTick); stageTick(); setTimeout(stageTick, 400); }

  /* Sichtbar werden */
  var io = new IntersectionObserver(function (entries) {
    entries.forEach(function (en) {
      if (!en.isIntersecting) return;
      en.target.classList.add('on'); io.unobserve(en.target);
    });
  }, { rootMargin: '0px 0px -4% 0px' });
  document.querySelectorAll('.rv, .fl, .rise, .station, .pola, .ph, [data-scatter], .lv').forEach(function (e) { if (!e.closest('[data-gs]')) io.observe(e); });
  /* Fakten: Funkenweg messen, Jahr hochzählen, sobald der Block im Bild ist */
  var facts = document.querySelector('[data-facts]');
  if (facts) {
    new IntersectionObserver(function (en, o) {
      if (!en[0].isIntersecting) return; o.disconnect();
      facts.style.setProperty('--w', facts.clientWidth + 'px');
      var cnt = facts.querySelector('[data-count]');
      if (cnt && !reduce) { var end = parseInt(cnt.dataset.count, 10), start = end - 12, t0 = null;
        var step = function (ts) { if (!t0) t0 = ts; var k = Math.min(1, (ts - t0 - 500) / 1300); if (k < 0) { requestAnimationFrame(step); return; } var e = 1 - Math.pow(1 - k, 3); cnt.textContent = Math.round(start + (end - start) * e); if (k < 1) requestAnimationFrame(step); };
        requestAnimationFrame(step); }
    }, { rootMargin: '0px 0px -10% 0px' }).observe(facts);
  }
  /* Video: wenn der Browser das Abspielen verweigert (Stromsparmodus), startet die erste Berührung alle sichtbaren Filme */
  function kick() { document.querySelectorAll('.film.near video').forEach(function (v) { var p = v.play(); if (p && p.catch) p.catch(function () {}); }); }
  ['touchstart', 'pointerdown', 'keydown'].forEach(function (ev) { addEventListener(ev, kick, { passive: true, once: true }); });

  /* Film-Fenster: Satz startet, Video lädt und läuft nur in der Nähe */
  var films = document.querySelectorAll('[data-film]');
  var fio = new IntersectionObserver(function (entries) {
    entries.forEach(function (en) {
      var f = en.target, v = f.querySelector('video');
      if (en.isIntersecting) {
        if (en.intersectionRatio > 0.35) f.classList.add('on');
        if (v && !v.dataset.ready) {
          v.dataset.ready = '1'; v.poster = v.dataset.poster;
          v.querySelectorAll('source').forEach(function (s) { s.src = s.dataset.src; }); v.load();
        }
        if (v) { var p = v.play(); if (p && p.catch) p.catch(function () {}); }
      } else if (v) { v.pause(); }
    });
  }, { rootMargin: '12% 0px 12% 0px', threshold: [0, 0.35] });
  films.forEach(function (f) { fio.observe(f); });
  var nio = new IntersectionObserver(function (entries) {
    entries.forEach(function (en) { en.target.classList.toggle('near', en.isIntersecting); });
  }, { rootMargin: '45% 0px 45% 0px' });
  films.forEach(function (f) { nio.observe(f); });

  /* Parallax: wenige Elemente, nur transform, nur im Bild */
  var pars = Array.prototype.map.call(document.querySelectorAll('[data-par]'), function (el) { return { el: el, k: parseFloat(el.dataset.par), top: 0, h: 0 }; });
  function measure() {
    vh = innerHeight;
    pars.forEach(function (p) { var r = p.el.getBoundingClientRect(); p.top = r.top + scrollY; p.h = r.height; });
    if (zp) { var rz = zp.getBoundingClientRect(); zp._top = rz.top + scrollY; zp._h = rz.height; }
    tick();
  }
  var ticking = false;
  function tick() {
    ticking = false;
    var y = scrollY;
    if (!reduce) pars.forEach(function (p) {
      if (p.top + p.h < y - vh || p.top > y + vh * 2) return;
      var c = p.top + p.h / 2 - (y + vh / 2);
      p.el.style.transform = 'translate3d(0,' + (-c * p.k).toFixed(1) + 'px,0)';
    });
    if (zp) {
      var pz = (y - zp._top) / (zp._h - vh);
      if (pz >= -0.05 && pz <= 1.05) {
        var q = Math.min(1, Math.max(0, pz));
        zpLayers.forEach(function (l) { l.el.style.transform = 'scale(' + (1 + (l.s - 1) * q).toFixed(4) + ')'; });
        zp.classList.toggle('fin', q > 0.78); zp.classList.toggle('on', q > 0.05);
        if (q > 0.78) { if (!zp._t) zp._t = setTimeout(function () { zp.classList.add('fin2'); }, 1100); } else if (zp._t) { clearTimeout(zp._t); zp._t = 0; zp.classList.remove('fin2'); }
      }
    }
  }
  function onScroll() { if (!ticking) { ticking = true; requestAnimationFrame(tick); } }
  addEventListener('scroll', onScroll, { passive: true });
  addEventListener('resize', measure);
  addEventListener('load', measure);
  measure();

  /* Pfad: Linie füllt bis zur letzten sichtbaren Station */
  var path = document.querySelector('[data-path]');
  if (path) {
    var rail = path.querySelector('.rail i'), stations = path.querySelectorAll('[data-station]');
    var sio = new IntersectionObserver(function () {
      var last = -1; stations.forEach(function (s, i) { if (s.classList.contains('on')) last = i; });
      if (last < 0) return;
      var r = path.getBoundingClientRect(), sr = stations[last].getBoundingClientRect();
      rail.style.transform = 'scaleY(' + Math.min(1, (sr.top - r.top + 12) / r.height).toFixed(3) + ')';
      rail.style.transition = 'transform .9s cubic-bezier(0.22, 1, 0.36, 1)';
    }, { rootMargin: '0px 0px -4% 0px' });
    stations.forEach(function (s) { sio.observe(s); });
  }

  /* Rahmen neigen sich zur Maus (nur Zeiger-Geräte) */
  if (matchMedia('(hover: hover) and (pointer: fine)').matches) {
    document.querySelectorAll('[data-tilt]').forEach(function (el) {
      el.addEventListener('mousemove', function (e) {
        var r = el.getBoundingClientRect();
        var x = (e.clientX - r.left) / r.width - 0.5, y = (e.clientY - r.top) / r.height - 0.5;
        el.style.setProperty('--ry', (x * 10).toFixed(2) + 'deg'); el.style.setProperty('--rx', (-y * 8).toFixed(2) + 'deg');
      });
      el.addEventListener('mouseleave', function () { el.style.setProperty('--ry', '0deg'); el.style.setProperty('--rx', '0deg'); });
    });
  }

  /* ========== Partnerschaft (Fassung 2, 01.11.2026): eigene Auftritte ========== */
  /* Gruppen mit [data-on] bekommen beim Hereinkommen .on; ihre .up-Teile und Fotos (.zf) folgen per CSS */
  document.querySelectorAll('[data-on]').forEach(function (e) { io.observe(e); });

/* Abschnitt hero */
try {

(function (root) {
  if (!root) return;
  var d = document.documentElement, wrap = root.parentNode;
  /* Auftritt: erst wenn die Seite sichtbar ist (Erster Blick), bei jedem Einblenden auf der Wahlseite neu */
  function play() {
    var els = [root].concat(Array.prototype.slice.call(root.querySelectorAll('.rise')));
    root.classList.add('x-reset');
    els.forEach(function (e) { e.classList.remove('on'); });
    void root.offsetWidth;
    root.classList.remove('x-reset');
    requestAnimationFrame(function () { requestAnimationFrame(function () { els.forEach(function (e) { e.classList.add('on'); }); if (root._play) root._play(); }); });
  }
  function ready(fn) { if (d.classList.contains('vor')) setTimeout(function () { ready(fn); }, 40); else fn(); }
  var seen = false;
  new IntersectionObserver(function (en, o) { if (en[0].isIntersecting && !seen) { seen = true; o.disconnect(); ready(play); } }).observe(root);
  if (wrap) wrap.addEventListener('wahl:zeigen', function () { seen = true; ready(play); });

})(document.querySelector('.s-hero'));

} catch (e) { console.error('Abschnitt hero', e); }
/* Abschnitt welt */
try {

(function (root) {
  if (!root) return;
  var wall = root.querySelector('.w8-wall'), cols = root.querySelectorAll('.w8-col'), figs = Array.prototype.slice.call(root.querySelector('.w8-src').content.querySelectorAll('.w8-f'));
  root.querySelectorAll('.w8-t').forEach(function (t, i) { t.classList.add('d' + (i + 1)); });
  var BIG = { 'stairs-800.webp': 'stairs-1400.webp 1400w', 'party-1000.webp': 'party-2000.webp 2000w', 'cube-800.webp': 'cube-1400.webp 1400w' };
  var mob = matchMedia('(max-width: 759px)').matches;
  figs.forEach(function (f) { var im = f.querySelector('img'), n = im.getAttribute('src').split('/').pop(); if (BIG[n]) { im.srcset = '/partner/media/' + n + ' ' + im.getAttribute('width') + 'w, /partner/media/' + BIG[n]; im.sizes = mob ? '50vw' : '34vw'; } });
  /* Rechner: drei Säulen (Treppe+Tram · Party+Pult · Negativ+Würfel) · Handy: zwei Säulen */
  var plan = mob ? [[0, 3, 2], [1, 4, 5]] : [[0, 3], [1, 4], [2, 5]];
  if (mob) cols[2].remove();
  plan.forEach(function (c, i) { c.forEach(function (k) { if (figs[k]) cols[i].appendChild(figs[k]); }); });
  cols = root.querySelectorAll('.w8-col');
  io.observe(wall);
  /* Tragende Bewegung: die Säulen der Wand laufen beim Scrollen gegeneinander, außen hinauf, in der Mitte hinab */
  var dir = mob ? [1, -1] : [1, -1, .7];
  function tick() {
    if (reduce || !root.getClientRects().length) return;
    var r = wall.getBoundingClientRect(); if (r.bottom < -50 || r.top > innerHeight + 50) return;
    var p = Math.min(1, Math.max(0, (innerHeight - r.top) / (innerHeight + r.height)));
    cols.forEach(function (c, i) {
      var range = Math.max(0, c.scrollHeight - r.height), d = dir[i], y = d > 0 ? -range * p * d : -range * (1 - p) * -d;
      c.style.transform = 'translate3d(0,' + y.toFixed(1) + 'px,0)';
    });
  }
  var t = false;
  addEventListener('scroll', function () { if (!t) { t = true; requestAnimationFrame(function () { t = false; tick(); }); } }, { passive: true });
  addEventListener('resize', tick); addEventListener('load', tick); root.addEventListener('wahl:zeigen', function () { setTimeout(tick, 30); }); tick();
  root.querySelectorAll('.w8-f img').forEach(function (im) { if (!im.complete) im.addEventListener('load', tick); });
})(document.querySelector('.s-welt'));

} catch (e) { console.error('Abschnitt welt', e); }
/* Abschnitt wir */
try {

(function (root) {
  if (!root) return;
  /* Der Code baut sich aus 8 × 8 Bausteinen auf, diagonal von oben links, jeder steigt aus seiner Zelle */
  var qr = root.querySelector('.qr'), n = 8, h = '';
  for (var r = 0; r < n; r++) for (var c = 0; c < n; c++) {
    var x = (c / (n - 1) * 100).toFixed(4) + '%', y = (r / (n - 1) * 100).toFixed(4) + '%';
    h += '<span class="q"><i style="--x:' + x + ';--y:' + y + ';--d:' + ((r + c) * 0.055).toFixed(3) + 's"></i></span>';
  }
  qr.innerHTML = h + '<span class="lg"><i></i></span>';
  io.observe(qr);
  var rw = root.querySelector('.rw'); io.observe(rw); rw.querySelectorAll('.zf').forEach(function (e) { io.observe(e); });
  var sf = root.querySelector('.sf'), ph = sf.querySelectorAll('.phone'), raf = 0;
  function tick() {
    raf = 0; if (reduce || !root.getClientRects().length) return;
    var r = sf.getBoundingClientRect(), h = innerHeight;
    var t = Math.min(1, Math.max(0, (h - r.top) / (h + r.height))) * 2 - 1;   /* -1 kommt herein … 1 geht hinaus */
    var a = Math.min(64, r.height * .08) * t;
    ph[0].style.setProperty('--py', a.toFixed(1) + 'px');
    ph[1].style.setProperty('--py', (-a).toFixed(1) + 'px');
  }
  function req() { if (!raf) raf = requestAnimationFrame(tick); }
  addEventListener('scroll', req, { passive: true }); addEventListener('resize', req); root.addEventListener('wahl:zeigen', req); tick();
})(document.querySelector('.s-wir'));

} catch (e) { console.error('Abschnitt wir', e); }
/* Abschnitt raender */
try {

(function (root) {
  if (!root) return;
  function vis() { return root.getClientRects().length > 0; }
  function cl(v) { return v < 0 ? 0 : v > 1 ? 1 : v; }
  function prog(el) { var r = el.getBoundingClientRect(), h = innerHeight; return cl((h - r.top) / (h + r.height)); }
  function watch(fn) { var q = false; function run() { q = false; if (vis()) fn(); } function req() { if (!q) { q = true; requestAnimationFrame(run); } }
    addEventListener('scroll', req, { passive: true }); addEventListener('resize', req); root.addEventListener('wahl:zeigen', function () { setTimeout(req, 30); }); req(); }
  var gr = root.querySelector('.gr'), img = root.querySelector('.fr img');
  root.querySelectorAll('.bk').forEach(function (b) { io.observe(b); });
  if (reduce) { img.style.setProperty('--s', 1); return; }
  watch(function () {
    var r = gr.getBoundingClientRect(), h = innerHeight;
    var t = cl((h * .9 - r.top) / (r.height));
    img.style.setProperty('--s', (1.14 - .14 * t).toFixed(4));
  });
})(document.querySelector('.s-raender'));

} catch (e) { console.error('Abschnitt raender', e); }
/* Abschnitt rollen */
try {

(function (root) {
  if (!root) return;
  io.observe(root.querySelector('.cb'));
})(document.querySelector('.s-rollen'));

} catch (e) { console.error('Abschnitt rollen', e); }
/* Abschnitt austausch */
try {

(function (root) {
  if (!root) return;
  root.querySelectorAll('.r-txt, .r-res').forEach(function (e) { io.observe(e); });
  var stage = root.querySelector('.r-stage'), floor = root.querySelector('.hero-room .floor');
  if (reduce) return;
  var t = false;
  /* Fahrt: von 0,8 auf 1, solange die Bühne vom unteren Rand bis in die Mitte steigt; der Boden zieht dabei unter einem durch */
  function upd() {
    t = false; if (!root.getClientRects().length) return;
    var vh = innerHeight, r = stage.getBoundingClientRect();
    var p = (vh - r.top) / (vh * 0.5 + r.height * 0.5); p = Math.max(0, Math.min(1, p));
    var e = 1 - Math.pow(1 - p, 2), s0 = innerWidth < 900 ? 0.86 : 0.8;
    stage.style.transform = 'scale(' + (s0 + (1 - s0) * e).toFixed(4) + ')';
    var rr = root.getBoundingClientRect(), q = Math.max(0, Math.min(1, -rr.top / Math.max(1, rr.height - vh)));
    if (floor) floor.style.transform = 'rotateX(72deg) translate3d(0,' + (q * 320).toFixed(1) + 'px,0)';
  }
  addEventListener('scroll', function () { if (!t) { t = true; requestAnimationFrame(upd); } }, { passive: true });
  addEventListener('resize', upd); root.addEventListener('wahl:zeigen', upd); upd();
})(document.querySelector('.s-austausch'));

} catch (e) { console.error('Abschnitt austausch', e); }
/* Abschnitt beispiele */
try {

(function (root) {
  if (!root) return;
  function obs(sel) { root.querySelectorAll(sel).forEach(function (e) { io.observe(e); }); }
  function clamp(v) { return v < 0 ? 0 : v > 1 ? 1 : v; }
  function loop(fn) { var t = false; function q() { if (t) return; t = true; requestAnimationFrame(function () { t = false; if (root.getClientRects().length) fn(); }); }
    addEventListener('scroll', q, { passive: true }); addEventListener('resize', q); root.addEventListener('wahl:zeigen', function () { setTimeout(q, 30); }); q(); }

  if (innerWidth >= 1200) { var vs = root.querySelector('.vs'); new IntersectionObserver(function (en, o) { if (!en[0].isIntersecting) return; o.disconnect(); vs.classList.add('on'); }, { threshold: 0.25 }).observe(vs); }
  else { obs('.vs-p'); root.querySelectorAll('.vs-c').forEach(function (e) { e.classList.add('rv'); io.observe(e); }); }
})(document.querySelector('.s-beispiele'));

} catch (e) { console.error('Abschnitt beispiele', e); }
/* Abschnitt beispiele */
try {

(function (root) {
  if (!root) return;
  root.querySelectorAll('.cs .up').forEach(function (e, i) { e.style.setProperty('--i', i); });
})(document.querySelector('.p-bsp'));

} catch (e) { console.error('Abschnitt beispiele', e); }
/* Abschnitt pilot */
try {

(function (root) {
  if (!root) return;
  var rows = root.querySelector('.rows'), segs = root.querySelectorAll('.bar > div'), txt = rows.querySelectorAll(':scope > div'), raf = 0;
  rows.querySelectorAll('figure').forEach(function (f) { io.observe(f); });
  txt.forEach(function (d) { io.observe(d); });
  io.observe(root.querySelector('.ms'));
  root.querySelectorAll('.ms .up').forEach(function (e, i) { e.style.setProperty('--i', i % 3); });
  function tick() {
    raf = 0; if (!root.getClientRects().length) return;
    var line = innerHeight * .6;
    /* Jeder Abschnitt der Leiste füllt sich, während sein Schritt durch die Bildmitte läuft */
    var figs = rows.querySelectorAll('figure'), fs = [];
    txt.forEach(function (d, i) {
      var r = d.getBoundingClientRect(), fig = figs[i].getBoundingClientRect();
      var top = Math.min(r.top, fig.top), bot = Math.max(r.bottom, fig.bottom);
      fs.push(reduce ? 1 : Math.min(1, Math.max(0, (line - top) / Math.max(1, bot - top))));
    });
    fs.forEach(function (f, i) {
      segs[i].style.setProperty('--f', f.toFixed(4));
      segs[i].classList.toggle('is', f > 0 && (i === fs.length - 1 || fs[i + 1] === 0));
    });
  }
  function req() { if (!raf) raf = requestAnimationFrame(tick); }
  addEventListener('scroll', req, { passive: true }); addEventListener('resize', req); root.addEventListener('wahl:zeigen', req); tick();
})(document.querySelector('.s-pilot'));

} catch (e) { console.error('Abschnitt pilot', e); }
/* Abschnitt wachsen */
try {

(function (root) {
  if (!root) return;
  root.querySelectorAll('.st-s').forEach(function (e, i) { e.style.setProperty('--k', i); e.style.setProperty('--i', i); });
})(document.querySelector('.p-wachsen'));

} catch (e) { console.error('Abschnitt wachsen', e); }
/* Abschnitt regeln */
try {

